#!/usr/bin/env bash
# H29: gVisor ladder; effect of one connection on restore; MPS against warmd on one GPU; segments under MPS.
cd /x/exp; X=/x; IMG=python:3.11-slim; R=/root/h29.jsonl; : > $R; E="env PYTHONPATH=/x/py HOME=/tmp"; V="-v $X:$X -v $X/exp:/workspace/exp -v $X/m:/workspace/m -w /workspace/exp"
nvidia-smi -pm 1 >/dev/null; sed -i 's#SOCK = "/tmp/vf.sock"#SOCK = "/x/vf.sock"#' h6b.py h8.py h9.py
broker() { docker rm -f xb >/dev/null 2>&1; docker run -d --name xb --gpus all -e GB=2 "$@" $V $IMG $E python3 h6b.py broker >/dev/null; for i in $(seq 120); do docker logs xb 2>&1 | grep -q ready && break; sleep 1; done; }
echo "== ladder"; broker
for t in ladder ckpt fork; do for pair in "runc:" "gvisor:--runtime=runscp"; do n=${pair%%:*}; a=${pair#*:}; timeout 120 docker run --rm $a --gpus all $V $IMG $E python3 h27.py $t $n 2>/root/h29_${t}_$n.err | tail -1 | cut -c1-460 | tee -a $R; done; done
echo "== one connection, runc"; for t in ladder ckpt; do timeout 120 docker run --rm --gpus all -e CUDA_DEVICE_MAX_CONNECTIONS=1 $V $IMG $E python3 h27.py $t runc_connections1 2>/dev/null | tail -1 | cut -c1-460 | tee -a $R; done
echo "== restore rate"; for c in default one; do a=""; [ $c = one ] && a="-e CUDA_DEVICE_MAX_CONNECTIONS=1"; broker; timeout 150 docker run --rm --gpus all --pid=host $a $V $IMG $E python3 h9.py 8 2>/root/h29_rate_$c.err | tail -1 | sed "s/^{/{\"connections\":\"$c\",/" | cut -c1-560 | tee -a $R; done; docker rm -f xb >/dev/null 2>&1
echo "== warmd on this GPU"; cd /x/warmd; make -s CUDA=/usr/local/cuda >/dev/null 2>/root/make.err || make -s CFLAGS_EXTRA="-I$(dirname $(find /root/tr -name cuda.h | head -1))" >/dev/null 2>>/root/make.err; ls build/warmd >/dev/null 2>&1 || { tail -n 3 /root/make.err | cut -c1-160; }; cd /x/exp; mkdir -p /x/w
if [ -x /x/warmd/build/warmd ]; then /x/warmd/build/warmd --socket /x/w/gpu0.sock --sessions 64 --standbys 0 > /root/warmd.log 2>&1 & W=$!; for i in $(seq 100); do grep -q ACTIVE /root/warmd.log && break; sleep 0.1; done; timeout 110 docker run --rm -e WARMD_SOCKET=/x/w/gpu0.sock -e WARMD_ALLOW_UNVALIDATED_DRIVER=1 -e LD_LIBRARY_PATH=/x/warmd/build/lib $V $IMG $E python3 h28_py.py conc warmd 2>/root/h29_warmd.err | tail -n 4 | cut -c1-200 | tee -a $R; kill $W; sleep 2; fi
echo "== segments under MPS"; mkdir -p /tmp/mps /tmp/mpsl; export CUDA_MPS_PIPE_DIRECTORY=/tmp/mps CUDA_MPS_LOG_DIRECTORY=/tmp/mpsl; nvidia-cuda-mps-control -d; sleep 2; M="--ipc=host -v /tmp/mps:/tmp/mps -e CUDA_MPS_PIPE_DIRECTORY=/tmp/mps"
broker $M; timeout 100 docker run --rm --gpus all $M $V $IMG $E python3 h27.py ladder mps 2>/root/h29_mps_ladder.err | tail -1 | cut -c1-460 | tee -a $R
echo "  mps hibernate"; timeout 100 docker run --rm --gpus all $M $V $IMG $E python3 h27.py ckpt mps 2>/dev/null | tail -1 | cut -c1-300 | tee -a $R
docker rm -f xb >/dev/null 2>&1; echo quit | nvidia-cuda-mps-control; sleep 2; unset CUDA_MPS_PIPE_DIRECTORY CUDA_MPS_LOG_DIRECTORY; nvidia-smi --query-gpu=memory.used --format=csv,noheader; tail -n 3 /root/h29_ladder_gvisor.err | cut -c1-200; echo h29-done
